 if g['id']=='notition':g['resterend']=g['resterend'].replace('De volledige lokale ronde en de gerichte echte Linux-debugvensters slagen','De volledige lokale ronde, alle vijf alpha43-CI-taken en de gerichte echte Linux-debug-/releasevensters slagen')
